it, minmax(200px, 1fr));\n  gap: var(--spacing-lg);\n}\n@media (max-width: 768px) {\n  .confirmation-actions[_ngcontent-%COMP%]   .actions-grid[_ngcontent-%COMP%] {\n    grid-template-columns: 1fr 1fr;\n    gap: var(--spacing-md);\n  }\n}\n.confirmation-actions[_ngcontent-%COMP%]   .actions-grid[_ngcontent-%COMP%]   .btn[_ngcontent-%COMP%] {\n  padding: var(--spacing-lg) var(--spacing-xl);\n  font-size: var(--font-size-sm);\n}\n@media (max-width: 768px) {\n  .confirmation-actions[_ngcontent-%COMP%]   .actions-grid[_ngcontent-%COMP%]   .btn[_ngcontent-%COMP%] {\n    padding: var(--spacing-md) var(--spacing-sm);\n    font-size: var(--font-size-xs);\n  }\n}\n\n.loading-container[_ngcontent-%COMP%], .error-container[_ngcontent-%COMP%] {\n  min-height: 60vh;\n  padding: var(--spacing-2xl);\n}\n.loading-container[_ngcontent-%COMP%]   .loading-spinner[_ngcontent-%COMP%], .error-container[_ngcontent-%COMP%]   .loading-spinner[_ngcontent-%COMP%] {\n  width: 40px;\n  height: 40px;\n  border: 3px solid var(--border-color);\n  border-top: 3px solid var(--primary-color);\n  border-radius: 50%;\n  animation: _ngcontent-%COMP%_spin 1s linear infinite;\n  margin-bottom: var(--spacing-lg);\n}\n.loading-container[_ngcontent-%COMP%]   p[_ngcontent-%COMP%], .error-container[_ngcontent-%COMP%]   p[_ngcontent-%COMP%] {\n  color: var(--text-secondary);\n  margin: 0;\n}\n\n.error-container[_ngcontent-%COMP%]   .error-content[_ngcontent-%COMP%] {\n  max-width: 400px;\n}\n.error-container[_ngcontent-%COMP%]   .error-content[_ngcontent-%COMP%]   h2[_ngcontent-%COMP%] {\n  color: #E74C3C;\n  margin-bottom: var(--spacing-lg);\n}\n.error-container[_ngcontent-%COMP%]   .error-content[_ngcontent-%COMP%]   p[_ngcontent-%COMP%] {\n  margin-bottom: var(--spacing-2xl);\n}\n\n@keyframes _ngcontent-%COMP%_spin {\n  0% {\n    transform: rotate(0deg);\n  }\n  100% {\n    transform: rotate(360deg);\n  }\n}\n@media (max-width: 768px) {\n  .confirmation-header[_ngcontent-%COMP%] {\n    padding: var(--spacing-3xl) 0;\n  }\n  .confirmation-header[_ngcontent-%COMP%]   .success-icon[_ngcontent-%COMP%] {\n    font-size: var(--font-size-3xl);\n  }\n  .confirmation-main[_ngcontent-%COMP%] {\n    padding: var(--spacing-3xl) 0;\n  }\n  .confirmation-layout[_ngcontent-%COMP%] {\n    grid-template-columns: 1fr;\n  }\n  .confirmation-sidebar[_ngcontent-%COMP%] {\n    order: -1;\n  }\n}\n.detail-section[_ngcontent-%COMP%], .card[_ngcontent-%COMP%] {\n  animation: _ngcontent-%COMP%_fadeInUp 0.6s ease-out;\n}\n\n@keyframes _ngcontent-%COMP%_fadeInUp {\n  from {\n    opacity: 0;\n    transform: translateY(20px);\n  }\n  to {\n    opacity: 1;\n    transform: translateY(0);\n  }\n}\n@media (prefers-reduced-motion: reduce) {\n  *[_ngcontent-%COMP%] {\n    animation-duration: 0.01ms;\n    animation-iteration-count: 1;\n    transition-duration: 0.01ms;\n  }\n}\n/*# sourceMappingURL=data:application/json;charset=utf-8;base64, */"]
